import { createClient } from '@nightmail/sdk/client';
import { listMcpConnections } from '@nightmail/sdk';

const client = createClient({
  baseUrl: 'https://nightmail.com',
  auth: scheme => scheme.scheme === 'bearer'
    ? process.env.NIGHTMAIL_API_KEY
    : undefined,
});

const result = await listMcpConnections({
  client,
  throwOnError: true,
});

console.log(result.data);

